<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetLanguages, GetSelectedLanguage, SetSelectedLanguage } from '@wails/go/gui/App.js';
	import { installState } from '$lib/store.svelte';
	import { t, setLocale, backendLocaleToFrontend } from '$lib/i18n';
	import '$lib/layout.css';

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	let languages = $state<Language[]>([]);
	let loading = $state(true);

	async function loadLanguages(): Promise<void> {
		try {
			languages = await GetLanguages();
			const saved = await GetSelectedLanguage();
			if (saved && languages.some(l => l.code === saved)) {
				installState.locale = saved;
			} else if (languages.length > 0) {
				installState.locale = languages[0].code;
				await SetSelectedLanguage(installState.locale);
			}
		} catch (err) {
			console.error(`Failed to load languages: ${err}`);
		} finally {
			loading = false;
		}
	}

	async function selectLanguage(code: string): Promise<void> {
		installState.locale = code;
		const lang = languages.find(l => l.code === code);
		const uiLocale = lang ? backendLocaleToFrontend(lang.locale) : undefined;

		try {
			await SetSelectedLanguage(code);
		} catch (err) {
			console.error(`Failed to set language: ${err}`);
		}

		if (uiLocale) {
			setLocale(uiLocale);
		}
	}

	loadLanguages();
</script>

<div class="page-content stretch">
		<div class="col col-left">
			<h2 class="page-title">{t('page.welcome.title')}</h2>
			<div class="subtitle-wrapper">
				<p class="subtitle">{t('page.welcome.subtitle')}</p>
			</div>
		</div>
		<div class="col col-right">
			{#if loading}
				<span class="loading-text">{t('page.welcome.loading')}</span>
			{:else}
				<ul class="language-list">
					{#each languages as lang (lang.code)}
						<li>
							<button
								type="button"
								class={['lang-item', { 'lang-item--selected': lang.code === installState.locale }]}
								onclick={() => selectLanguage(lang.code)}
							>
								{lang.name}
							</button>
						</li>
					{/each}
				</ul>
			{/if}
		</div>
	</div>

